import React, { useState, useEffect } from "react";
import { Card, Typography } from "@mui/material";
import Navigation from "./Navigation";

const AboutUs = () => {
  const [currentPage, setCurrentPage] = useState("home");

  const handleNavigation = (page) => {
    setCurrentPage(page);
    window.location.hash = "#" + page;
  };
  return (
    <div className="navigation-top">
    <Navigation handleNavigation={handleNavigation} />
  
    <Card style={{ padding: "16px", maxWidth: "900px", margin: "auto", marginTop: "80px" }} className="img-card">
      <Typography variant="h6" style={{ textAlign: "center" }}>About Us</Typography>
      <Typography variant="body1" style={{ textAlign: "center" }}>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Integer nec odio. Praesent libero. Sed cursus ante dapibus diam.</Typography>
    </Card>
    </div>
  );
};

export default AboutUs;
